styl:
.w280 { width: 100%;
  max-width: 280px; }
@media screen and (max-width: 600px) {
  .w280 { max-width: 100% !important; }
}
.w280-2 { display: inline-block;
  width: 59%;
  vertical-align: bottom; }
@media screen and (max-width: 600px) {
  .w280-2 { max-width: 100% !important;
    width: 100% !important;
    display: block !important; }
}
.bottom-img { display: inline-block;
  width: 39%;
  float: right;
  vertical-align: middle; }
@media screen and (max-width: 600px) {
  .bottom-img { width: 1px !important;
    max-width: 0.1px !important; }
}
@media screen and (max-width: 600px) {
  .line-mob { border: 4px solid #f70; }
}
.brad-full { border-radius: 32px !important; }
.butt-link { font-size: 18px;
  line-height: 27px;
  font-weight: 700;
  text-transform: none;
  text-decoration: none;
  color: #f9f9f9;
  display: block;
  padding: 16px 0 16px;
  text-align: center;
  letter-spacing: 0px; }
.white-bg { background-color: #fff; }
.middle-title { font-family: Helvetica !important;
  font-weight: 700;
  font-size: 32px;
  line-height: 42px;
  color: #393a44;
  vertical-align: middle; }
@media screen and (max-width: 600px) {
  .middle-title { font-size: 28px !important;
    line-height: 34px !important; }
}
.text { font-family: Helvetica !important;
  font-size: 18px;
  color: #393a44;
  letter-spacing: 0;
  line-height: 26px;
  font-weight: 400; }
.text.bold { font-weight: 700; }
.pb12 { padding-bottom: 12px !important; }
.pb44 { padding-bottom: 44px; }
.pt15 { padding-top: 15px; }
.pt44 { padding-top: 44px; }
@media screen and (max-width: 600px) {
  .text.mob-text,
  .grey-text.mob-text { font-size: 17px !important; }
}
